from pathlib import Path
import ast
root=Path(__file__).parent/'.runs'
reader=root/'read-universal-shift-interface-native-paired240-001.py'
s=reader.read_text()
s=s.replace('    def stable():\n        # Large tool files',"    result_pin=execution_pin=None\n    def stable():\n        # Large tool files",1)
s=s.replace("        h.owned_destination(owner)\n        require(inventory(base)==material", "        h.owned_destination(owner)\n        # Reuse the strict Native event replay AFTER all tool/freeze callbacks.\n        # Byte inventories alone do not witness flags or hard-link counts.\n        for worker in result['workers']:\n            cwd=Path(worker['cwd']);name=worker['name'];process=f.read_json(cwd/(name+'-process.json'))\n            argv=process['argv'];command=argv[len(f.SANDBOX):] if argv[:len(f.SANDBOX)]==f.SANDBOX else argv\n            if command[:3]==[str(c.CLI),'pcb','drc']:\n                binding=f.read_json(cwd/(name+'-binding.json'))\n                failed=process['status']!='success' and not (process['status']=='nonzero_exit' and process.get('exit_code')==5)\n                ls.check_event(cwd,binding,process,allow_worker_failure=failed)\n        require(inventory(base)==material",1)
s=s.replace("        require(remaining()>0,'reader45-second wall/fullCPU allowance exceeded')", "        if result_pin is not None:require(p.sha(output/'result.json')==result_pin,'published reader receipt changed during final callbacks')\n        if execution_pin is not None:require(p.sha(output/'execution.json')==execution_pin,'reader execution changed during final callbacks')\n        require(remaining()>0,'reader45-second wall/fullCPU allowance exceeded')",1)
s=s.replace("    f.publish(output,result,stable,account,remaining,owned=lambda:h.owned_destination(owner),final_check=final_bound)\n    stable()", "    f.publish(output,result,stable,account,remaining,owned=lambda:h.owned_destination(owner),final_check=final_bound)\n    require(f.canonical(f.read_json(output/'result.json'))==f.canonical(result),'published reader receipt differs')\n    result_pin=p.sha(output/'result.json')\n    stable()",1)
s=s.replace("result_sha256=p.sha(output/'result.json'),\n        final_charged_results", "result_sha256=result_pin,\n        final_charged_results",1)
s=s.replace("    stable();require(p.sha(output/'result.json')==f.read_json(output/'execution.json')['result_sha256'],'final reader receipt differs')", "    execution_pin=p.sha(output/'execution.json')\n    stable()\n    require(p.sha(output/'result.json')==result_pin and p.sha(output/'execution.json')==execution_pin,'final reader receipts changed')\n    require(f.read_json(output/'execution.json')['result_sha256']==result_pin,'final reader receipt differs')",1)
assert s!=reader.read_text();ast.parse(s);reader.write_text(s)
wrapper=root/'run-universal-shift-interface-native-paired240-readback-001.py'
s=wrapper.read_text().replace('placement_clearance as pc','placement_clearance as pc,local_settings as ls,config as c',1)
s=s.replace('board=Path(spec[\'source\']);readback_witness=None',"board=Path(spec['source']);readback_witness=None;prl_workers=[];execution_pin=None",1)
s=s.replace(" require(pc.inventory(BASE,max_bytes", " for worker in prl_workers:\n  cwd=Path(worker['cwd']);name=worker['name'];process=f.read_json(cwd/(name+'-process.json'));argv=process['argv']\n  command=argv[len(f.SANDBOX):] if argv[:len(f.SANDBOX)]==f.SANDBOX else argv\n  if command[:3]==[str(c.CLI),'pcb','drc']:\n   binding=f.read_json(cwd/(name+'-binding.json'));failed=process['status']!='success' and not (process['status']=='nonzero_exit' and process.get('exit_code')==5)\n   ls.check_event(cwd,binding,process,allow_worker_failure=failed)\n require(pc.inventory(BASE,max_bytes",1)
s=s.replace('==readback_witness)\nstable()',"==readback_witness)\n if execution_pin is not None:require(p.sha(OUT/'execution.json')==execution_pin)\nstable()",1)
s=s.replace(" require(inner['result_sha256']==p.sha(READEROUT/'result.json'))", " result_pin=p.sha(READEROUT/'result.json');inner_pin=p.sha(READEROUT/'execution.json');prl_workers=result['workers']\n require(inner['result_sha256']==result_pin)",1)
s=s.replace("result_sha256=p.sha(READEROUT/'result.json'),reader_execution_sha256=p.sha(READEROUT/'execution.json')", "result_sha256=result_pin,reader_execution_sha256=inner_pin",1)
s=s.replace("p.save_json(OUT/'execution.json',record);print", "p.save_json(OUT/'execution.json',record)\nexecution_pin=p.sha(OUT/'execution.json')\ntry:\n stable()\n require(p.sha(OUT/'execution.json')==execution_pin)\n require(time.monotonic()-START<=record['wall_seconds']+2 and cpu()-CPU0<=record['full_cpu_seconds']+2)\n require(max(time.monotonic()-START,cpu()-CPU0)<=CAP)\nexcept BaseException as exc:\n record.update(passed=False,source_current=False,reason=type(exc).__name__+': '+str(exc),wall_seconds=time.monotonic()-START,full_cpu_seconds=cpu()-CPU0)\n p.save_json(OUT/'execution.json',record)\nprint",1)
